CREATE TABLE IF NOT EXISTS `devhub_licenses_templates` (
  `name` varchar(70) NOT NULL,
  `label` varchar(255) DEFAULT NULL,
  `layout` varchar(50) NOT NULL DEFAULT '{}',
  `texture` longtext NOT NULL DEFAULT '{}',
  `background` longtext NOT NULL DEFAULT '{}',
  `components` longtext NOT NULL DEFAULT '{}',
  `expirationDays` int(11) NOT NULL DEFAULT 30,
  `grantPermissions` longtext NOT NULL DEFAULT '{"all": true}',
  `canBeFaked` int(11) NOT NULL DEFAULT 1,
  `autoIssue` int(11) NOT NULL DEFAULT 0,
  `chargeForIssue` int(11) NOT NULL DEFAULT 0,
  `itemName` varchar(100) NOT NULL DEFAULT '',
  PRIMARY KEY (`name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

