CREATE TABLE IF NOT EXISTS `devhub_licenses_licenses` (
  `id` varchar(12) NOT NULL,
  `originalOwner` varchar(255) DEFAULT NULL,
  `owner` varchar(46) DEFAULT NULL,
  `templateName` varchar(70) NOT NULL,
  `data` longtext NOT NULL DEFAULT '{}',
  `issueDate` timestamp NULL DEFAULT NULL,
  `expirationDate` int(11) unsigned DEFAULT NULL,
  `isFake` tinyint(4) NOT NULL DEFAULT 0,
  `isFavorite` int(11) NOT NULL DEFAULT 0,
  `suspensionTime` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','suspended','lost','expired','revoked') DEFAULT 'active',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `devhub_licenses_users` (
  `identifier` varchar(46) NOT NULL,
  `fullName` varchar(255) DEFAULT NULL,
  `history` longtext NOT NULL DEFAULT '{}',
  `granted` longtext NOT NULL DEFAULT '{}',
  PRIMARY KEY (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
